fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    // Determine the length of the broadcasted arrays
    let len = m.max(n);

    // If `a` has length 1, repeat its only element `len` times; otherwise clone it.
    let out_a = if m == 1 {
        vec![a[0]; len]
    } else {
        a.clone()
    };

    // If `b` has length 1, repeat its only element `len` times; otherwise clone it.
    let out_b = if n == 1 {
        vec![b[0]; len]
    } else {
        b.clone()
    };

    (out_a, out_b)
}

